<?php
declare( strict_types = 1 );

namespace MediaWiki\OutputTransform\Stages;

use MediaWiki\Config\ServiceOptions;
use MediaWiki\OutputTransform\OutputTransformStage;
use MediaWiki\Parser\ContentHolder;
use MediaWiki\Parser\ParserOptions;
use MediaWiki\Parser\ParserOutput;
use MediaWiki\Parser\ParserOutputFlags;
use MediaWiki\Revision\SlotRoleRegistry;
use Psr\Log\LoggerInterface;
use Wikimedia\Parsoid\DOM\DocumentFragment;
use Wikimedia\Parsoid\Utils\DOMCompat;

/**
 * Hydrate slot section header placeholders generated by RevisionRenderer.
 * @internal
 */
class HydrateHeaderPlaceholders extends OutputTransformStage {
	public function __construct(
		ServiceOptions $options,
		LoggerInterface $logger,
		private SlotRoleRegistry $roleRegistry,
	) {
		parent::__construct( $options, $logger );
	}

	public function shouldRun( ParserOutput $po, ParserOptions $popts, array $options = [] ): bool {
		return !$po->getExtensionData( 'core:hydrated' ) &&
			( (bool)$po->getExtensionData( 'core:slots' ) ||
				// For backwards compat, until the parser cache clears
				$po->getOutputFlag( ParserOutputFlags::HAS_SLOT_HEADERS ) );
	}

	public function transform( ParserOutput $po, ParserOptions $popts, array &$options ): ParserOutput {
		$po->setExtensionData( 'core:hydrated', true );
		$contentHolder = $po->getContentHolder();

		if ( !$contentHolder->isParsoidContent() ) {
			$text = $contentHolder->getAsHtmlString(
				ContentHolder::BODY_FRAGMENT
			) ?? '';
			$text = preg_replace_callback( '#<mw:slotheader>(.*?)</mw:slotheader>#', static function ( $m ) {
				$role = htmlspecialchars_decode( $m[1] );
				// TODO: map to message, using the interface language. Set lang="xyz" accordingly.
				$headerText = $role;

				return $headerText;
			}, $text );
			$contentHolder->setAsHtmlString( ContentHolder::BODY_FRAGMENT, $text );
			return $po;
		}

		$fragment = $contentHolder->getAsDom();
		'@phan-var DocumentFragment $fragment';

		$wrapperDivClass = AddWrapperDivClass::wrapperDivClass( $po, $popts, $options );
		if ( $wrapperDivClass !== null ) {
			$fragment = DOMCompat::querySelector( $fragment, ".$wrapperDivClass" );
		}

		foreach ( $po->getExtensionData( 'core:slots' ) ?? [] as $role => $value ) {
			// TODO: put more fancy layout logic here, see T200915.
			$roleHandler = $this->roleRegistry->getRoleHandler( $role );
			$layout = $roleHandler->getOutputLayoutHints();
			$display = $layout['display'] ?? 'section';

			if ( $display === 'none' ) {
				continue;
			}

			$fragmentName = "slot-$role";
			$df = $contentHolder->getAsDom( $fragmentName );
			'@phan-var DocumentFragment $df';
			$contentHolder->setAsDom( $fragmentName, null );

			// TODO: map to message, using the interface language. Set lang="xyz" accordingly.
			$headerText = $role;

			$h1 = $df->ownerDocument->createElement( 'h1' );
			DOMCompat::getClassList( $h1 )->add( 'mw-slot-header' );
			$h1->appendChild( $df->ownerDocument->createTextNode( $headerText ) );
			$df->insertBefore( $h1, $df->firstChild );

			$fragment->appendChild( $df );
		}

		return $po;
	}
}
